function leagueTargetLabel(s=season){const target=E.target(s);return s.league.rules==='legacy'?(target===1?'리그 우승':target+'위 이내'):s.league.division===2?'1부 승격 · 2위 이내':'1부 잔류 · 6위 이내';}
function seasonHeadline(finished,me){if(finished){if(me.rank===1)return season.league.division===2?'우승, 그리고 더 높은 무대.':'마침내, 1부의 정상에.';const move=S.movement(season);return move.kind==='promotion'?'우리의 다음 무대는 1부.':move.kind==='relegation'?'다시 올라갈 준비를.':'시즌은 끝나도 구단은 자란다.';}return season.league.division===2?'구단 현황':'이제, 강팀들의 무대로.';}
function leagueZone(c){if(season.league.division===2&&c.rank<=2)return {kind:'promotion',label:'승격권'};if(season.league.division===1&&c.rank>=7)return {kind:'relegation',label:'강등권'};if(season.league.division===1&&c.rank===1)return {kind:'champion',label:'선두'};return null;}
function movementText(h){return h.nextDivision<h.division?'1부 승격':h.nextDivision>h.division?'2부 강등':h.division+'부 잔류';}
function renderDivision(table,me){
 const tier=S.divisionInfo(season),top=season.league.division===1,finishedLeague=season.round===14,move=S.movement(season),rates=E.rates(season),previous=season.history.at(-1),boundary=table[top?5:1];
 const status=finishedLeague?(move.kind==='promotion'?'1부 승격 확정':move.kind==='relegation'?'2부 강등 확정':top&&me.rank===1?'1부 우승':season.league.division+'부 잔류'):!season.round?'첫 경기를 기다립니다.':top?(me.rank>=7?'강등권 · 반등이 필요합니다.':me.rank===1?'현재 1부 선두.':'현재 잔류권.'):me.rank<=2?'현재 승격권.':'승격권을 향해.';
 const detail=finishedLeague?(!S.ready(season)?'남은 컵 일정을 마치면 다음 시즌으로 넘어갑니다.':'다음 시즌은 '+S.divisionInfo(move.to).name+'에서 시작합니다.'):season.round?(top?'잔류선 6위':'승격선 2위')+' '+boundary.points+'점 · 우리 구단 '+me.points+'점':top?'1부 7~8위는 다음 시즌 2부로 내려갑니다.':'2부 1~2위는 다음 시즌 1부로 올라갑니다.';
 $('league-journey').innerHTML=`<section class="division-panel" aria-label="승격과 강등"><div class="division-route"><div class="division-step ${!top?'active':''}"><span>DIVISION 02</span><strong>로우랜드 리그</strong><small>1~2위 → 1부 승격</small></div><span class="division-link" aria-hidden="true">⇄</span><div class="division-step ${top?'active':''}"><span>DIVISION 01</span><strong>${S.divisionInfo(1).name}</strong><small>7~8위 → 2부 강등</small></div></div><div class="division-status ${finishedLeague&&move.kind==='relegation'?'danger':''}"><div><span class="eyebrow">${finishedLeague?'FINAL DESTINATION':'THE ROAD UP'}</span><h2>${status}</h2><p>${detail}</p></div><div class="division-income"><span>${tier.division}부 홈 경기 수입</span><b>${moneyLabel(rates.gateHome)}</b><small>+ 후원 ${moneyLabel(rates.sponsor)} / 경기</small></div></div>${previous?'<p class="division-recap">지난 시즌 · '+previous.division+'부 '+previous.rank+'위 · '+movementText(previous)+'</p>':''}${season.league.rules==='legacy'?'<p class="division-legacy">기존 시즌의 목표와 정산을 유지합니다. 이번 시즌 1~2위로 마치면 1부에 승격합니다.</p>':''}<p class="division-footnote">각 리그 8개 구단 · 홈과 원정 14경기 · 현재 소속 리그의 컵 참가</p></section>`;
}
